package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Defers an OPEN claim until a date after the sheet's today. A claim in any other status, a date not after the sheet's
 * today, or a claim whose due-by is in a closed period is refused. Returns the date, for the audit.
 */
public class ApplyDefer {
    public LocalDate apply(@Val Claim claim, @Val Sheet sheet, ClaimRepository repository, PeriodRepository periods,
            @RequestParam(name = "until", required = false) String untilParam) throws ClaimStatusException {
        if (periods.isClosedOn(claim.getSheetId(), claim.getDueBy())) {
            throw new ClaimStatusException("A claim in a closed period cannot be deferred.");
        }
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new ClaimStatusException("A " + claim.getStatus() + " claim cannot be deferred.");
        }
        LocalDate until;
        try {
            until = LocalDate.parse(untilParam == null ? "" : untilParam.trim());
        } catch (DateTimeParseException e) {
            throw new ClaimStatusException("Not a date: " + untilParam);
        }
        if (!until.isAfter(sheet.getToday())) {
            throw new ClaimStatusException("A claim can only be deferred to a date after the sheet's today.");
        }
        claim.setDeferredUntil(until);
        repository.saveAndFlush(claim);
        return until;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.AuditUser;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestHeader;

/** Records the deferral, once it is saved: the claim's line, then the date it is deferred until. */
public class AuditClaimDeferred {
    public void audit(@Parameter LocalDate until, @Val Claim claim, PersonRepository people,
            @RequestHeader(name = "X-User", required = false) String user, Audit audit) {
        String person = people.findById(claim.getPersonId()).map(Person::getName).orElse("");
        audit.record(ClaimAudit.line("CLAIM_DEFERRED", claim, person, AuditUser.decode(user)) + " until=" + until);
    }
}
package net.officefloor.hq.app.claim;

/** A claim's audit line: the event, sheet, user, person, amount as the screen shows it, date, and the claim's
 * number when it has one. */
public final class ClaimAudit {

    private ClaimAudit() {
    }

    public static String line(String event, Claim claim, String person, String user) {
        return line(event, claim, person, user, claim.getNumber());
    }

    static String line(String event, Claim claim, String person, String user, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow (or an unknown action). */
public class ClaimStatusException extends Exception {
    public ClaimStatusException(String message) {
        super(message);
    }
}
